class Solution {
    int minVal;
    int secondMin;
    bool found;

    void dfs(TreeNode* node) {
        if (!node) return;
        if (node->val > minVal) {
            if (!found || node->val < secondMin) {
                secondMin = node->val;
                found = true;
            }
            return;
        }
        dfs(node->left);
        dfs(node->right);
    }

public:
    int findSecondMinimumValue(TreeNode* root) {
        minVal = root->val;
        found = false;
        secondMin = 0;
        dfs(root);
        return found ? secondMin : -1;
    }
};
